import{_ as i,l as s,o as e,c as o,v as t,p as n,x as l,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"Splay 与摊还","description":"","frontmatter":{"title":"Splay 与摊还","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/splay-tree.md","filePath":"cs/splay-tree.md","lastUpdated":1789023840000}'),h={name:"cs/splay-tree.md"};function m(g,a,_,S,T,u){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="splay-与摊还" tabindex="-1">Splay 与摊还 <a class="header-anchor" href="#splay-与摊还" aria-label="Permalink to &quot;Splay 与摊还&quot;">​</a></h1><div class="epigraph"><p>每次访问把目标旋到根；单次可能线性，一串访问的摊还却是对数——没有随机，也没有颜色位。</p><footer>—— 据 Sleator and Tarjan, Self-Adjusting Binary Search Trees, JACM 1985；Tarjan, Amortized Computational Complexity, 1985 整理</footer></div><p><a href="/cs/treap">上一课</a>靠随机优先级。<a href="/cs/amortized-analysis">摊还分析</a>已在动态数组上练过势能。<a href="/cs/bst">BST</a> 旋转原语现成。本课不抛硬币。缺口是伸展树：访问后 splay 到根，摊还 \\(O(\\log n)\\)，并得到动态最优性一类推论的入口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工作集若有局部性（刚访问的键很快再访问），平衡树仍每次从根走 \\(\\log n\\)，不「变矮」。Splay：查找/插入/删除后，把目标（或删除的父）用 zig / zig-zig / zig-zag 转到根。单次可能 \\(\\Theta(n)\\)。缺口是证明<strong>任意 \\(m\\) 次操作总时间 \\(O((m+n)\\log n)\\)</strong>（或更细的工作集界），而不是最坏每次对数。</p><p><span class="marginnote">势能常取 \\(\\sum \\log(\\mathrm{size}(u))\\)。zig-zig 是摊还分析里真正省时间的一步：一次转两个，比两次 zig 便宜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>zig：目标是根的孩子，单旋。zig-zig：目标与父同侧，先旋祖父再旋父。zig-zag：折线，先旋父再旋祖父。插入当 BST 插入再 splay；删除可 splay 目标，合并左右子树（右子树最小 splay 上来接左）。</p>',8)),(e(),n(c,null,{default:l(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%AE%BF%E9%97%AE%20k%22%5D%20--%3E%20SP%5B%22splay%20%E5%88%B0%E6%A0%B9%22%5D%0A%20%20SP%20--%3E%20ZIG%5B%22zig%20%2F%20zig-zig%20%2F%20zig-zag%22%5D%0A%20%20SP%20--%3E%20AM%5B%22%E6%91%8A%E8%BF%98%20O(log%20n)%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 Treap/红黑：无额外字段、无随机；缓存局部性差时常数可能输给红黑。合同是摊还不是最坏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>静态最优性、工作集定理：频繁键会在靠近根处停留一段时间。这不是概率期望，是对任意序列的摊还。不要把 splay 当成「每次 \\(O(\\log n)\\) 最坏」写进实时路径。</p><p>并发 splay 几乎不用：旋转改根，锁粒度粗。本课串行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明完整势能全部引理，只钉合同与三种旋转形状。不引入 tango 树。顺序统计（秩、第 \\(k\\)）可在任一平衡 BST 上加 size，下一课专收，不绑死 splay。</p><p>后课默认：自调整 BST 摊还对数。要 <code>select</code>/<code>rank</code>，加子树计数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Splay：访问旋到根，摊还对数，无随机无颜色。</li><li>单次可线性；实时用确定平衡树。</li><li>下一课在平衡 BST 上加顺序统计。</li><li>出处：Sleator and Tarjan, <em>JACM</em>, 1985。</li></ul>',9))])}const z=i(h,[["render",m]]);export{y as __pageData,z as default};
